const [actuals, setActuals] = useState<ActualEntry[]>([]);

useEffect(() => {
  if (!isWip || !project.ft_project_name) return;
  fetch(`/api/conduit/actuals?project=${encodeURIComponent(project.ft_project_name)}`)
    .then(r => r.json())
    .then(d => { if (d.data) setActuals(d.data); })
