  month: string;        // "2025-07"
  category: string;     // "Ad Hoc" | "Casuals" | "Fuel" | "Overheads" | "Sales" | "Stock" | "Sub-Contractor" | "Wayleaves" | "Revenue"
  amount: number;
}
```

