'use client';

import { Handle, Position } from 'reactflow';

interface TableNodeData {
  label: string;
  module: string;
  columns: number;
  onSelect: () => void;
  isSelected: boolean;
}

export function TableNode({ data }: { data: TableNodeData }) {
  return (
    <div
      onClick={data.onSelect}
      className={`px-4 py-2 rounded-lg text-white font-semibold cursor-pointer transition-all text-sm ${
        data.isSelected ? 'ring-2 ring-blue-400' : ''
      }`}
    >
      <div className="font-bold text-xs text-white/80 mb-1">{data.module.toUpperCase()}</div>
      <div className="truncate">{data.label}</div>
      <div className="text-xs text-white/70 mt-1">{data.columns} col{data.columns !== 1 ? 's' : ''}</div>
      <Handle type="target" position={Position.Top} />
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}

'use client';

import { Search, X } from 'lucide-react';

interface SearchFilterProps {
  search: string;
  onSearchChange: (value: string) => void;
}

export function SearchFilter({ search, onSearchChange }: SearchFilterProps) {
  return (
    <div className="relative flex-1 max-w-md">
      <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[var(--ff-text-tertiary)]" />
      <input
        type="text"
        placeholder="Search tables by name or module..."
        value={search}
        onChange={(e) => onSearchChange(e.target.value)}
        className="w-full pl-10 pr-9 py-2 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder-[var(--ff-text-tertiary)] focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
      />
      {search && (
        <button
          onClick={() => onSearchChange('')}
          className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
        >
          <X className="w-4 h-4" />
        </button>
      )}
    </div>
  );
}

'use client';

import { Database, Columns3, Link2, LucideIcon, AlertCircle } from 'lucide-react';
import type { SchemaStats } from '../types';

interface StatCardProps {
  icon: LucideIcon;
  label: string;
  value: number;
  color: string;
}

function StatCard({ icon: Icon, label, value, color }: StatCardProps) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 flex items-center gap-3">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon className="w-5 h-5 text-white" />
      </div>
      <div>
        <p className="text-sm text-[var(--ff-text-secondary)]">{label}</p>
        <p className="text-2xl font-bold text-[var(--ff-text-primary)]">{value}</p>
      </div>
    </div>
  );
}

interface StatsBarProps {
  stats: SchemaStats;
}

export function StatsBar({ stats }: StatsBarProps) {
  return (
    <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-4 gap-3">
        <StatCard icon={Database} label="Total Tables" value={stats.totalTables} color="bg-blue-600" />
        <StatCard icon={Columns3} label="Total Columns" value={stats.totalColumns} color="bg-green-600" />
        <StatCard icon={Link2} label="FK Relationships" value={stats.totalForeignKeys} color="bg-purple-600" />
        <StatCard icon={AlertCircle} label="Isolated Tables" value={stats.isolatedTables} color="bg-amber-600" />
      </div>
    </div>
  );
}

'use client';

import { X, Key, Link2, Type } from 'lucide-react';
import type { TableInfo, SchemaData } from '../types';

interface TablePanelProps {
  table: TableInfo;
  schema: SchemaData;
  onNavigate: (table: TableInfo) => void;
}

export function TablePanel({ table, schema, onNavigate }: TablePanelProps) {
  return (
    <div className="w-96 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden flex flex-col">
      {/* Header */}
      <div className="border-b border-[var(--ff-border-light)] p-4">
        <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">{table.name}</h2>
        <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
          Module: <span className="font-semibold text-[var(--ff-text-secondary)]">{table.module}</span>
        </p>
      </div>

      {/* Columns */}
      <div className="flex-1 overflow-y-auto">
        <div className="p-4 space-y-3">
          <h3 className="text-sm font-semibold text-[var(--ff-text-primary)] flex items-center gap-2">
            <Type className="w-4 h-4" />
            Columns ({table.columns.length})
          </h3>

          <div className="space-y-2">
            {table.columns.map((col) => (
              <div
                key={col.name}
                className="bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded p-3 text-xs"
              >
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-[var(--ff-text-primary)]">{col.name}</span>
                  {col.isPrimaryKey && <Key className="w-3 h-3 text-blue-600" title="Primary Key" />}
                  {col.isForeignKey && <Link2 className="w-3 h-3 text-green-600" title="Foreign Key" />}
                </div>
                <div className="text-[var(--ff-text-tertiary)] mt-1">
                  {col.dataType}
                  {col.nullable ? ', nullable' : ', NOT NULL'}
                </div>
                {col.defaultValue && (
                  <div className="text-[var(--ff-text-tertiary)] mt-1">
                    Default: <code className="bg-black/20 px-1 rounded">{col.defaultValue}</code>
                  </div>
                )}
                {col.foreignKeyReferences && (
                  <button
                    onClick={() => {
                      const refTable = schema.tables.find((t) => t.name === col.foreignKeyReferences?.table);
                      if (refTable) onNavigate(refTable);
                    }}
                    className="text-blue-600 hover:text-blue-700 font-semibold mt-2"
                  >
                    → {col.foreignKeyReferences.table}.{col.foreignKeyReferences.column}
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="border-t border-[var(--ff-border-light)] p-4 text-xs text-[var(--ff-text-tertiary)]">
        Primary Key: <span className="font-semibold">{table.primaryKey || 'None'}</span>
      </div>
    </div>
  );
}

